package com.universalplatform.assignment;
import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.JpaRepository;
public interface AssignmentSubmissionRepository extends JpaRepository<AssignmentSubmission,UUID>{ Optional<AssignmentSubmission> findTopByTenantIdAndAssignmentIdAndMembershipIdOrderByAttemptNumberDesc(UUID tenantId,UUID assignmentId,UUID membershipId); List<AssignmentSubmission> findAllByTenantIdAndAssignmentIdAndMembershipIdOrderByAttemptNumberDesc(UUID tenantId,UUID assignmentId,UUID membershipId); List<AssignmentSubmission> findAllByTenantIdAndAssignmentId(UUID tenantId,UUID assignmentId); Page<AssignmentSubmission> findAllByTenantIdAndAssignmentId(UUID tenantId,UUID assignmentId,Pageable p); Page<AssignmentSubmission> findAllByTenantIdAndMembershipId(UUID tenantId,UUID membershipId,Pageable p); }
